mapper.sql:
select ebr.batch_id as "batchId", ebr.job_type as "jobType", case ebr.job_type when 'GENERATION' then '생성' when 'DELETION' then '삭제' when 'RECALCULATION' then '재계산' when 'CONFIRMATION' then '확정' else ebr.job_type end as "jobTypeName", ebrq.request_status as "requestStatus", ebrq.target_condition_json::text as "targetCondition", ebr.total_count as "totalCount", ebr.success_count as "successCount", ebr.failure_count as "failureCount", ebr.excluded_count as "excludedCount", ebr.request_id as "requestId", to_char(ebrq.requested_at, 'YYYY-MM-DD"T"HH24:MI:SS') as "requestedAt", to_char(ebrq.completed_at, 'YYYY-MM-DD"T"HH24:MI:SS') as "completedAt" from evaluation_batch_results ebr join evaluation_batch_requests ebrq on ebrq.batch_id = ebr.batch_id where 1 = 1
and ebr.batch_id = #{criteria.normalizedBatchId}
and ebr.job_type = #{criteria.normalizedJobType}
and ebrq.target_condition_json::text ilike concat('%', #{criteria.normalizedTargetCondition}, '%')
